window.OWN_BUNDLES=window.OWN_BUNDLES||{};window.OWN_BUNDLES["posthog"]={html:"<div class=\"own-posthog\">\n  <a class=\"ph-skip\" href=\"#phMain\">Skip to content</a>\n\n  <!-- ── NAV ─────────────────────────────────────────────────────────── -->\n  <header class=\"ph-nav\" id=\"phNav\">\n    <div class=\"ph-nav-in\">\n      <a class=\"ph-brand\" href=\"#phMain\" aria-label=\"Northwind home\">\n        <span class=\"ph-hedge\" data-ph-hedge aria-hidden=\"true\"></span>\n        <span class=\"ph-brand-name\">Northwind</span>\n      </a>\n      <nav class=\"ph-nav-links\" aria-label=\"Primary\">\n        <a href=\"#phProduct\">Product</a>\n        <a href=\"#phDocs\">Docs</a>\n        <a href=\"#phPricing\">Pricing</a>\n        <a href=\"#phWorkflows\">Workflows</a>\n        <a href=\"#phCommunity\">Community</a>\n      </nav>\n      <div class=\"ph-nav-actions\">\n        <a class=\"ph-login\" href=\"#\">Log in</a>\n        <a class=\"ph-btn ph-btn-primary\" href=\"#phPricing\">Get started — free</a>\n      </div>\n    </div>\n  </header>\n\n  <main id=\"phMain\">\n    <!-- ── HERO ───────────────────────────────────────────────────────── -->\n    <section class=\"ph-hero\">\n      <div class=\"ph-wrap ph-hero-in\">\n        <div class=\"ph-hero-copy\">\n          <p class=\"ph-eyebrow\">Open-source operations analytics</p>\n          <h1 class=\"ph-display-xl\">The new way to see your operations.</h1>\n          <p class=\"ph-lead\">Northwind is the operations analytics platform your data team will actually enjoy. Track regions, throughput, and revenue on one warm, quiet sheet — with the mascots doing the heavy lifting.</p>\n          <div class=\"ph-hero-cta\">\n            <a class=\"ph-btn ph-btn-primary\" href=\"#phPricing\">Get started — free</a>\n            <a class=\"ph-btn ph-btn-secondary\" href=\"#phDocs\">Read the docs</a>\n          </div>\n          <p class=\"ph-hero-note\">Free self-host · No credit card · SOC 2 Type II</p>\n        </div>\n        <div class=\"ph-hero-art\" aria-hidden=\"true\">\n          <span class=\"ph-hedge ph-hedge-lg\" data-ph-hedge aria-hidden=\"true\"></span>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── FEATURE TILES ──────────────────────────────────────────────── -->\n    <section class=\"ph-section\" id=\"phProduct\">\n      <div class=\"ph-wrap\">\n        <div class=\"ph-sec-head\">\n          <p class=\"ph-eyebrow\">Product</p>\n          <h2 class=\"ph-display-lg\">Everything an ops team needs</h2>\n          <p class=\"ph-sec-lead\">Start with dashboards, go as deep as the ledger. Northwind keeps every surface on the same cream canvas.</p>\n        </div>\n        <div class=\"ph-tiles\" id=\"phTiles\"></div>\n      </div>\n    </section>\n\n    <!-- ── WORKFLOWS — code block inside cream card ───────────────────── -->\n    <section class=\"ph-section ph-section-soft\" id=\"phWorkflows\">\n      <div class=\"ph-wrap\">\n        <div class=\"ph-sec-head\">\n          <p class=\"ph-eyebrow\">Workflows</p>\n          <h2 class=\"ph-display-lg\">Automate the reports you hate</h2>\n        </div>\n        <div class=\"ph-work-grid\">\n          <article class=\"ph-work-card\">\n            <span class=\"ph-hedge ph-hedge-sm\" data-ph-hedge aria-hidden=\"true\"></span>\n            <h3 class=\"ph-heading-sm-mixed\">Set an alert in seconds</h3>\n            <p class=\"ph-body-sm\">Define a threshold once. Northwind watches every region and pages the on-call before the SLA slips.</p>\n            <pre class=\"ph-code\"><code><span class=\"ph-c-kw\">northwind</span>.alert({\n  metric: <span class=\"ph-c-str\">'throughput.on_time'</span>,\n  below:  <span class=\"ph-c-num\">0.95</span>,\n  notify: <span class=\"ph-c-str\">'#ops-oncall'</span>\n})</code></pre>\n          </article>\n          <div class=\"ph-work-side\">\n            <p class=\"ph-banner ph-banner-blue\"><b>Tip.</b> Pipe any threshold to Slack, PagerDuty, or a webhook — no glue code.</p>\n            <p class=\"ph-banner ph-banner-green\"><b>Success.</b> Alerts resolve themselves when the metric recovers, so the channel stays quiet.</p>\n            <p class=\"ph-banner ph-banner-red\"><b>Warning.</b> A region with no data at all counts as a miss — wire your sources first.</p>\n            <p class=\"ph-banner ph-banner-purple\"><b>Note.</b> Every alert keeps a history you can query with <code class=\"ph-inline-code\">northwind.query()</code>.</p>\n          </div>\n        </div>\n      </div>\n    </section>\n\n    <!-- ── PRICING ────────────────────────────────────────────────────── -->\n    <section class=\"ph-section\" id=\"phPricing\">\n      <div class=\"ph-wrap\">\n        <div class=\"ph-sec-head\">\n          <p class=\"ph-eyebrow\">Pricing</p>\n          <h2 class=\"ph-display-lg\">Simple, usage-based pricing</h2>\n        </div>\n        <div class=\"ph-pricing\" id=\"phPricingGrid\"></div>\n      </div>\n    </section>\n\n    <!-- ── DOC LAYOUT — sidebar + article ─────────────────────────────── -->\n    <section class=\"ph-section\" id=\"phDocs\">\n      <div class=\"ph-wrap ph-docs\">\n        <aside class=\"ph-doc-side\" aria-label=\"Docs sections\">\n          <form class=\"ph-doc-search\" role=\"search\" onsubmit=\"return false\">\n            <svg viewBox=\"0 0 24 24\" aria-hidden=\"true\"><circle cx=\"11\" cy=\"11\" r=\"7\"/><path d=\"m20 20-4-4\"/></svg>\n            <input type=\"search\" placeholder=\"Ask Northwind AI\" aria-label=\"Ask Northwind AI\">\n          </form>\n          <nav class=\"ph-doc-nav\" id=\"phDocNav\"></nav>\n        </aside>\n        <article class=\"ph-doc-card\">\n          <p class=\"ph-eyebrow\">Getting started</p>\n          <h2 class=\"ph-heading-lg\">Build your first operations dashboard</h2>\n          <p class=\"ph-body-sm\">A Northwind dashboard is a set of panels on one ledger. Connect a source, pin a metric, and share the board with the whole operations team.</p>\n          <p class=\"ph-banner ph-banner-blue\"><b>Tip.</b> Start from a template board if you'd rather not build panels by hand.</p>\n          <h3 class=\"ph-heading-sm-mixed\">Connect a data source</h3>\n          <pre class=\"ph-code\"><code><span class=\"ph-c-kw\">import</span> { Northwind } <span class=\"ph-c-kw\">from</span> <span class=\"ph-c-str\">'@northwind/sdk'</span>\n<span class=\"ph-c-kw\">const</span> nw = <span class=\"ph-c-kw\">new</span> Northwind({ key: process.env.<span class=\"ph-c-kw\">NW_KEY</span> })</code></pre>\n          <h3 class=\"ph-heading-sm-mixed\">Pin a metric</h3>\n          <p class=\"ph-body-sm\">Every panel is a query. Pin quarterly throughput and Northwind recomputes the board as the work lands.</p>\n        </article>\n      </div>\n    </section>\n  </main>\n\n  <!-- ── FOOTER ───────────────────────────────────────────────────────── -->\n  <footer class=\"ph-foot\" id=\"phCommunity\">\n    <div class=\"ph-wrap\">\n      <div class=\"ph-foot-grid\">\n        <div><p class=\"ph-foot-head\">Product</p><a href=\"#phProduct\">Dashboards</a><a href=\"#phWorkflows\">Workflows</a><a href=\"#phPricing\">Pricing</a></div>\n        <div><p class=\"ph-foot-head\">Resources</p><a href=\"#phDocs\">Docs</a><a href=\"#\">Blog</a><a href=\"#\">Changelog</a></div>\n        <div><p class=\"ph-foot-head\">Company</p><a href=\"#\">About</a><a href=\"#\">Careers</a></div>\n        <div><p class=\"ph-foot-head\">Legal</p><a href=\"#\">Privacy</a><a href=\"#\">Terms</a></div>\n      </div>\n      <div class=\"ph-foot-bottom\">\n        <span class=\"ph-foot-brand\"><span class=\"ph-hedge ph-hedge-xs\" data-ph-hedge aria-hidden=\"true\"></span> Northwind</span>\n        <span>© 2026 · Sample data — showcase only</span>\n      </div>\n    </div>\n  </footer>\n</div>\n",css:"/* ══ POSTHOG — Northwind operations analytics, built in PostHog's real page grammar ══\n   Warm-cream canvas end-to-end, olive ink, IBM Plex Sans, single yellow-orange CTA,\n   hand-drawn hedgehog mascots (CSS+SVG), dark code islands inside white cards, pastel\n   callout banners. Scoped under `.own-posthog`. */\n\n.own-posthog {\n  --primary: #f7a501;\n  --primary-pressed: #dd9001;\n  --on-primary: #23251d;\n  --ink: #23251d;\n  --body: #4d4f46;\n  --charcoal: #33342d;\n  --mute: #6c6e63;\n  --ash: #9b9c92;\n  --stone: #b6b7af;\n  --hairline: #bfc1b7;\n  --hairline-soft: #dcdfd2;\n  --on-dark: #ffffff;\n  --canvas: #eeefe9;\n  --surface-soft: #e5e7e0;\n  --surface-card: #ffffff;\n  --surface-doc: #fcfcfa;\n  --surface-dark: #23251d;\n  --link-blue: #1d4ed8;\n  --link-teal: #1078a3;\n  --accent-blue-soft: #dceaf6;\n  --accent-red-soft: #f7d6d3;\n  --accent-green-soft: #d9eddf;\n  --accent-purple-soft: #e7d8ee;\n  --focus-ring: rgba(59,130,246,.5);\n\n  --f-sans: 'IBM Plex Sans Variable', 'IBM Plex Sans', -apple-system, system-ui, 'Segoe UI', Roboto, sans-serif;\n  --f-mono: ui-monospace, 'Source Code Pro', 'IBM Plex Mono', Menlo, monospace;\n\n  --r-xs: 2px;\n  --r-sm: 4px;\n  --r-md: 6px;\n  --r-lg: 8px;\n  --r-full: 9999px;\n  --gut: clamp(16px, 4.6cqi, 40px);\n  --sec: clamp(44px, 7cqi, 80px);\n\n  position: relative;\n  background: var(--canvas);\n  color: var(--body);\n  font-family: var(--f-sans);\n  font-size: 16px;\n  line-height: 1.5;\n  text-align: left;\n  overflow-x: clip;\n  -webkit-font-smoothing: antialiased;\n}\n\n.own-posthog *, .own-posthog *::before, .own-posthog *::after { box-sizing: border-box; }\n.own-posthog p { margin: 0; }\n.own-posthog h1, .own-posthog h2, .own-posthog h3 { margin: 0; }\n.own-posthog a { color: inherit; text-decoration: none; }\n.own-posthog img, .own-posthog svg { display: block; }\n.own-posthog button { font: inherit; }\n.own-posthog :focus-visible { outline: 2px solid var(--link-blue); outline-offset: 2px; border-radius: 6px; }\n\n.own-posthog .ph-wrap { width: 100%; max-width: 1280px; margin: 0 auto; padding: 0 var(--gut); }\n\n.own-posthog .ph-skip {\n  position: absolute; left: 12px; top: -60px; z-index: 60;\n  padding: 10px 16px; border-radius: var(--r-md); background: var(--ink); color: var(--on-dark);\n  font-weight: 700; transition: top .2s;\n}\n.own-posthog .ph-skip:focus { top: 12px; }\n\n/* ── type ────────────────────────────────────────────────────────────── */\n.own-posthog .ph-display-xl { font-size: clamp(28px, 4cqi, 36px); font-weight: 700; line-height: 1.35; color: var(--ink); }\n.own-posthog .ph-display-lg { font-size: clamp(24px, 3.4cqi, 34px); font-weight: 800; line-height: 1.33; letter-spacing: -.6px; color: var(--ink); }\n.own-posthog .ph-heading-lg { font-size: clamp(19px, 2cqi, 21px); font-weight: 700; line-height: 1.4; letter-spacing: -.5px; color: var(--ink); }\n.own-posthog .ph-heading-sm-mixed { font-size: 18px; font-weight: 600; line-height: 1.56; color: var(--ink); }\n.own-posthog .ph-eyebrow { font-size: 12px; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; color: var(--mute); margin-bottom: 12px; }\n.own-posthog .ph-lead { font-size: clamp(16px, 1.4cqi, 18px); line-height: 1.6; color: var(--body); }\n.own-posthog .ph-body-sm { font-size: 15px; line-height: 1.71; color: var(--body); }\n.own-posthog .ph-sec-lead { font-size: 16px; line-height: 1.6; color: var(--body); max-width: 60ch; margin-top: 10px; }\n.own-posthog .ph-sec-head { max-width: 720px; margin-bottom: clamp(24px, 4cqi, 40px); }\n\n/* ── buttons ─────────────────────────────────────────────────────────── */\n.own-posthog .ph-btn {\n  display: inline-flex; align-items: center; justify-content: center; gap: 8px;\n  height: 40px; padding: 8px 16px; border-radius: var(--r-md);\n  font-size: 14px; font-weight: 700; line-height: 1.5; white-space: nowrap;\n  transition: background-color .15s, transform .15s;\n}\n.own-posthog .ph-btn-primary { background: var(--primary); color: var(--on-primary); }\n.own-posthog .ph-btn-primary:hover { background: var(--primary-pressed); }\n.own-posthog .ph-btn-primary:active { transform: scale(.98); }\n.own-posthog .ph-btn-secondary { background: var(--surface-soft); color: var(--ink); }\n.own-posthog .ph-btn-secondary:hover { background: var(--hairline-soft); }\n\n/* ── nav ─────────────────────────────────────────────────────────────── */\n.own-posthog .ph-nav { position: sticky; top: 68px; z-index: 40; background: var(--canvas); border-bottom: 1px solid var(--hairline); }\n.own-posthog .ph-nav-in { display: flex; align-items: center; gap: 20px; height: 56px; max-width: 1280px; margin: 0 auto; padding: 0 var(--gut); }\n.own-posthog .ph-brand { display: flex; align-items: center; gap: 8px; flex: none; }\n.own-posthog .ph-brand-name { font-size: 19px; font-weight: 700; color: var(--ink); }\n.own-posthog .ph-nav-links { display: flex; gap: 4px; flex: 1 1 auto; }\n.own-posthog .ph-nav-links a { font-size: 16px; font-weight: 600; color: var(--ink); padding: 8px 12px; border-radius: var(--r-md); }\n.own-posthog .ph-nav-links a:hover { background: var(--surface-soft); }\n.own-posthog .ph-nav-actions { display: flex; align-items: center; gap: 12px; margin-left: auto; }\n.own-posthog .ph-login { font-size: 15px; font-weight: 600; color: var(--ink); }\n\n/* ── hedgehog mascot (pure CSS) ──────────────────────────────────────── */\n.own-posthog .ph-hedge {\n  position: relative; width: 40px; height: 30px; flex: none; display: inline-block; vertical-align: middle;\n}\n.own-posthog .ph-hedge::before {\n  content: ''; position: absolute; inset: 2px 0 0 0;\n  background: var(--ink);\n  border-radius: 46% 46% 40% 40% / 60% 60% 40% 40%;\n  -webkit-mask: repeating-conic-gradient(from 200deg at 70% 40%, transparent 0deg 6deg, #000 6deg 12deg);\n  mask: repeating-conic-gradient(from 200deg at 70% 40%, transparent 0deg 6deg, #000 6deg 12deg);\n}\n.own-posthog .ph-hedge::after {\n  content: ''; position: absolute; left: -4px; top: 12px; width: 16px; height: 14px;\n  background: #f4e2c4; border-radius: 50% 50% 45% 55%;\n}\n.own-posthog .ph-hedge i, .own-posthog .ph-hedge b { position: absolute; }\n.own-posthog .ph-hedge .ph-eye { left: 2px; top: 13px; width: 3px; height: 3px; border-radius: 50%; background: var(--ink); }\n.own-posthog .ph-hedge .ph-nose { left: -4px; top: 18px; width: 4px; height: 4px; border-radius: 50%; background: var(--ink); }\n.own-posthog .ph-hedge-lg { width: 180px; height: 130px; }\n.own-posthog .ph-hedge-sm { width: 54px; height: 40px; }\n.own-posthog .ph-hedge-xs { width: 26px; height: 20px; }\n\n/* ── hero ────────────────────────────────────────────────────────────── */\n.own-posthog .ph-hero { padding: clamp(36px, 6cqi, 80px) 0; }\n.own-posthog .ph-hero-in { display: grid; grid-template-columns: 1.15fr .85fr; gap: clamp(24px, 4cqi, 56px); align-items: center; }\n.own-posthog .ph-hero .ph-lead { max-width: 54ch; margin: 18px 0 26px; }\n.own-posthog .ph-hero-cta { display: flex; gap: 12px; flex-wrap: wrap; }\n.own-posthog .ph-hero-note { font-size: 14px; font-weight: 500; color: var(--mute); margin-top: 16px; }\n.own-posthog .ph-hero-art { display: grid; place-items: center; min-height: 220px; }\n\n/* ── sections ────────────────────────────────────────────────────────── */\n.own-posthog .ph-section { padding: var(--sec) 0; }\n.own-posthog .ph-section-soft { background: var(--surface-soft); }\n\n/* ── feature tiles ───────────────────────────────────────────────────── */\n.own-posthog .ph-tiles { display: grid; grid-template-columns: repeat(4, 1fr); gap: 16px; }\n.own-posthog .ph-tile {\n  position: relative; background: var(--surface-card); border: 1px solid var(--hairline);\n  border-radius: var(--r-md); padding: 20px; overflow: hidden; min-height: 200px;\n  display: flex; flex-direction: column; gap: 10px;\n}\n.own-posthog .ph-tile .ph-hedge-sm { position: absolute; top: 16px; right: 16px; }\n.own-posthog .ph-tile-icon { width: 44px; height: 44px; border-radius: var(--r-md); display: grid; place-items: center; background: var(--surface-soft); }\n.own-posthog .ph-tile-icon svg { width: 24px; height: 24px; fill: none; stroke: var(--ink); stroke-width: 1.8; stroke-linecap: round; stroke-linejoin: round; }\n.own-posthog .ph-tile-title { font-size: 18px; font-weight: 600; line-height: 1.4; color: var(--ink); margin-top: 4px; }\n.own-posthog .ph-tile-body { font-size: 15px; line-height: 1.6; color: var(--body); }\n.own-posthog .ph-tile-link { margin-top: auto; font-size: 14px; font-weight: 600; color: var(--link-teal); }\n\n/* ── workflows ───────────────────────────────────────────────────────── */\n.own-posthog .ph-work-grid { display: grid; grid-template-columns: 1.4fr .9fr; gap: 24px; align-items: start; }\n.own-posthog .ph-work-card {\n  position: relative; background: var(--surface-card); border: 1px solid var(--hairline);\n  border-radius: var(--r-md); padding: 24px;\n}\n.own-posthog .ph-work-card .ph-hedge-sm { position: absolute; top: 20px; right: 24px; }\n.own-posthog .ph-work-card h3 { margin-bottom: 12px; }\n.own-posthog .ph-work-side { display: grid; gap: 14px; }\n\n.own-posthog .ph-code {\n  margin: 18px 0 0; background: var(--surface-dark); color: var(--on-dark);\n  border-radius: var(--r-md); padding: 16px 20px; overflow-x: auto;\n  font-family: var(--f-mono); font-size: 14px; line-height: 1.43;\n}\n.own-posthog .ph-code code { font-family: inherit; }\n.own-posthog .ph-c-kw { color: #7dd3fc; }\n.own-posthog .ph-c-str { color: #86efac; }\n.own-posthog .ph-c-num { color: #d8b4fe; }\n\n.own-posthog .ph-inline-code {\n  background: var(--surface-soft); color: var(--ink); border-radius: var(--r-xs);\n  padding: 2px 6px; font-family: var(--f-mono); font-size: 14px; font-weight: 500;\n}\n\n.own-posthog .ph-banner {\n  border-radius: var(--r-md); padding: 16px 20px; font-size: 16px; line-height: 1.5; color: var(--ink);\n}\n.own-posthog .ph-banner b { font-weight: 700; }\n.own-posthog .ph-banner-blue { background: var(--accent-blue-soft); }\n.own-posthog .ph-banner-green { background: var(--accent-green-soft); }\n.own-posthog .ph-banner-red { background: var(--accent-red-soft); }\n.own-posthog .ph-banner-purple { background: var(--accent-purple-soft); }\n\n/* ── pricing ─────────────────────────────────────────────────────────── */\n.own-posthog .ph-pricing { display: grid; grid-template-columns: repeat(3, 1fr); gap: 20px; align-items: start; }\n.own-posthog .ph-tier {\n  background: var(--surface-card); border: 1px solid var(--hairline); border-radius: var(--r-md);\n  padding: 32px; display: flex; flex-direction: column; gap: 16px;\n}\n.own-posthog .ph-tier-featured { background: var(--ink); color: var(--on-dark); border-color: var(--ink); }\n.own-posthog .ph-tier-name { font-size: 24px; font-weight: 800; letter-spacing: -.6px; }\n.own-posthog .ph-tier-price { font-size: 40px; font-weight: 800; letter-spacing: -1px; line-height: 1; }\n.own-posthog .ph-tier-price small { font-size: 15px; font-weight: 500; color: var(--mute); }\n.own-posthog .ph-tier-featured .ph-tier-price small { color: rgba(255,255,255,.7); }\n.own-posthog .ph-tier ul { list-style: none; margin: 0; padding: 0; display: grid; gap: 10px; }\n.own-posthog .ph-tier li { display: flex; gap: 10px; font-size: 15px; line-height: 1.5; color: var(--body); }\n.own-posthog .ph-tier-featured li { color: rgba(255,255,255,.85); }\n.own-posthog .ph-tier li svg { width: 18px; height: 18px; flex: none; fill: none; stroke: var(--link-teal); stroke-width: 2.4; stroke-linecap: round; stroke-linejoin: round; margin-top: 2px; }\n.own-posthog .ph-tier .ph-btn { margin-top: auto; }\n\n/* ── docs ────────────────────────────────────────────────────────────── */\n.own-posthog .ph-docs { display: grid; grid-template-columns: 240px 1fr; gap: clamp(24px, 4cqi, 56px); align-items: start; }\n.own-posthog .ph-doc-side { position: sticky; top: 148px; }\n.own-posthog .ph-doc-search {\n  display: flex; align-items: center; gap: 8px; height: 36px; padding: 8px 12px;\n  background: var(--surface-card); border: 1px solid var(--hairline); border-radius: var(--r-md); margin-bottom: 18px;\n}\n.own-posthog .ph-doc-search svg { width: 16px; height: 16px; fill: none; stroke: var(--mute); stroke-width: 2; flex: none; }\n.own-posthog .ph-doc-search input { width: 100%; border: 0; background: none; color: var(--ink); font: inherit; font-size: 14px; outline: none; }\n.own-posthog .ph-doc-search input::placeholder { color: var(--ash); }\n.own-posthog .ph-doc-nav { display: grid; gap: 4px; }\n.own-posthog .ph-doc-nav a {\n  display: flex; align-items: center; gap: 10px; font-size: 14px; font-weight: 500; color: var(--body);\n  padding: 8px 10px; border-radius: var(--r-md);\n}\n.own-posthog .ph-doc-nav a:hover { background: var(--surface-soft); }\n.own-posthog .ph-doc-nav a.on { background: var(--surface-card); color: var(--ink); border: 1px solid var(--hairline); }\n.own-posthog .ph-doc-nav svg { width: 20px; height: 20px; flex: none; fill: none; stroke: var(--body); stroke-width: 1.6; stroke-linecap: round; stroke-linejoin: round; }\n.own-posthog .ph-doc-card { background: var(--surface-doc); border: 1px solid var(--hairline); border-radius: var(--r-md); padding: 32px; }\n.own-posthog .ph-doc-card h2 { margin-bottom: 14px; }\n.own-posthog .ph-doc-card h3 { margin: 26px 0 10px; }\n.own-posthog .ph-doc-card p { margin-bottom: 14px; }\n.own-posthog .ph-doc-card .ph-code { margin-top: 0; }\n\n/* ── footer ──────────────────────────────────────────────────────────── */\n.own-posthog .ph-foot { background: var(--canvas); border-top: 1px solid var(--hairline); padding: 32px 0; }\n.own-posthog .ph-foot-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 24px; }\n.own-posthog .ph-foot-grid > div { display: flex; flex-direction: column; gap: 10px; }\n.own-posthog .ph-foot-head { font-size: 12px; font-weight: 700; letter-spacing: .06em; text-transform: uppercase; color: var(--mute); margin-bottom: 4px; }\n.own-posthog .ph-foot-grid a { font-size: 14px; font-weight: 500; color: var(--body); }\n.own-posthog .ph-foot-grid a:hover { color: var(--ink); }\n.own-posthog .ph-foot-bottom {\n  display: flex; align-items: center; justify-content: space-between; gap: 16px; flex-wrap: wrap;\n  margin-top: 28px; padding-top: 20px; border-top: 1px solid var(--hairline-soft); font-size: 12px; color: var(--mute);\n}\n.own-posthog .ph-foot-brand { display: inline-flex; align-items: center; gap: 8px; font-size: 15px; font-weight: 700; color: var(--ink); }\n\n/* ── responsive ──────────────────────────────────────────────────────── */\n@container frame (max-width: 1100px) {\n  .own-posthog .ph-tiles { grid-template-columns: repeat(2, 1fr); }\n  .own-posthog .ph-nav-links { display: none; }\n}\n@container frame (max-width: 760px) {\n  .own-posthog .ph-hero-in { grid-template-columns: 1fr; }\n  .own-posthog .ph-hero-art { display: none; }\n  .own-posthog .ph-work-grid { grid-template-columns: 1fr; }\n  .own-posthog .ph-pricing { grid-template-columns: 1fr; }\n  .own-posthog .ph-docs { grid-template-columns: 1fr; }\n  .own-posthog .ph-doc-side { position: static; }\n  .own-posthog .ph-doc-nav { grid-auto-flow: column; grid-auto-columns: max-content; overflow-x: auto; gap: 8px; }\n  .own-posthog .ph-doc-nav a { white-space: nowrap; }\n  .own-posthog .ph-foot-grid { grid-template-columns: repeat(2, 1fr); }\n}\n@container frame (max-width: 430px) {\n  .own-posthog .ph-tiles { grid-template-columns: 1fr; }\n  .own-posthog .ph-hero-cta { flex-direction: column; }\n  .own-posthog .ph-hero-cta .ph-btn { width: 100%; }\n  .own-posthog .ph-foot-grid { grid-template-columns: 1fr; }\n}\n\n@media (prefers-reduced-motion: reduce) {\n  .own-posthog *, .own-posthog *::before, .own-posthog *::after {\n    animation-duration: .001ms !important; transition-duration: .001ms !important;\n  }\n}\n"};
/* ══ POSTHOG — Northwind operations analytics ═══════════════════════════════════
   Registers window.OWN_LAYOUTS['posthog'].init(root). Renders the feature tiles,
   pricing tiers and doc sidebar from sample data; highlights the active doc item
   on scroll. Returns a cleanup that disconnects the observer. */

(function () {
  var OWN = (window.OWN_LAYOUTS = window.OWN_LAYOUTS || {});

  function esc(s) {
    return String(s == null ? '' : s).replace(/[&<>"']/g, function (c) {
      return { '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c];
    });
  }

  var ICONS = {
    chart: 'M4 19V9M10 19V5M16 19v-7M22 19H2',
    funnel: 'M4 5h16l-6 7v6l-4 2v-8z',
    pulse: 'M3 12h4l2-6 4 12 2-6h6',
    flag: 'M6 4v16M6 5h11l-2 4 2 4H6'
  };

  var TILES = [
    { icon: 'chart', title: 'Dashboards', body: 'Pin the metrics your team checks every morning, on one warm sheet.', link: 'Explore dashboards' },
    { icon: 'funnel', title: 'Funnels', body: 'See where throughput drops off across regions, step by step.', link: 'Build a funnel' },
    { icon: 'pulse', title: 'Alerts', body: 'Thresholds that page the on-call before the SLA ever slips.', link: 'Set an alert' },
    { icon: 'flag', title: 'Workflows', body: 'Automate the recurring report with a query, not a spreadsheet.', link: 'See workflows' }
  ];

  var TIERS = [
    { name: 'Free', price: '$0', per: 'forever', feats: ['1M events / mo', 'Unlimited dashboards', 'Community support'], cta: 'Start free', featured: false },
    { name: 'Scale', price: '$450', per: '/mo', feats: ['20M events / mo', 'Alerts & workflows', 'Priority support'], cta: 'Start free', featured: true },
    { name: 'Enterprise', price: 'Custom', per: '', feats: ['Unlimited events', 'SSO & audit log', 'Dedicated engineer'], cta: 'Talk to sales', featured: false }
  ];

  var DOCS = [
    { icon: 'chart', label: 'Dashboards', on: true },
    { icon: 'funnel', label: 'Funnels', on: false },
    { icon: 'pulse', label: 'Alerts', on: false },
    { icon: 'flag', label: 'Workflows', on: false },
    { icon: 'chart', label: 'Data sources', on: false },
    { icon: 'funnel', label: 'API reference', on: false }
  ];

  OWN['posthog'] = {
    init: function (root) {
      var AC = window.AbortController ? new AbortController() : null;
      var signal = AC ? AC.signal : undefined;
      var observers = [];
      var $ = function (s) { return root.querySelector(s); };
      var $$ = function (s) { return Array.prototype.slice.call(root.querySelectorAll(s)); };
      function on(el, type, fn, opt) {
        if (!el) return;
        opt = Object.assign({}, opt || {});
        if (signal) opt.signal = signal;
        el.addEventListener(type, fn, opt);
      }

      var tiles = $('#phTiles');
      if (tiles) {
        tiles.innerHTML = TILES.map(function (t) {
          return '<a class="ph-tile" href="#">'
            + '<span class="ph-hedge ph-hedge-sm" aria-hidden="true"></span>'
            + '<span class="ph-tile-icon"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="' + esc(ICONS[t.icon]) + '"/></svg></span>'
            + '<span class="ph-tile-title">' + esc(t.title) + '</span>'
            + '<span class="ph-tile-body">' + esc(t.body) + '</span>'
            + '<span class="ph-tile-link">' + esc(t.link) + ' →</span></a>';
        }).join('');
      }

      var pricing = $('#phPricingGrid');
      if (pricing) {
        pricing.innerHTML = TIERS.map(function (t) {
          return '<div class="ph-tier' + (t.featured ? ' ph-tier-featured' : '') + '">'
            + '<span class="ph-tier-name">' + esc(t.name) + '</span>'
            + '<span class="ph-tier-price">' + esc(t.price) + ' <small>' + esc(t.per) + '</small></span>'
            + '<ul>' + t.feats.map(function (f) {
              return '<li><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 12l4 4 10-10"/></svg>' + esc(f) + '</li>';
            }).join('') + '</ul>'
            + '<a class="ph-btn ' + (t.featured ? 'ph-btn-primary' : 'ph-btn-secondary') + '" href="#">' + esc(t.cta) + '</a></div>';
        }).join('');
      }

      var docNav = $('#phDocNav');
      if (docNav) {
        docNav.innerHTML = DOCS.map(function (d) {
          return '<a href="#" class="' + (d.on ? 'on' : '') + '">'
            + '<svg viewBox="0 0 24 24" aria-hidden="true"><path d="' + esc(ICONS[d.icon]) + '"/></svg>'
            + esc(d.label) + '</a>';
        }).join('');
      }

      /* active doc item on click */
      on(docNav, 'click', function (e) {
        var a = e.target.closest('a');
        if (!a) return;
        e.preventDefault();
        $$('.ph-doc-nav a').forEach(function (x) { x.classList.toggle('on', x === a); });
      });

      return function cleanup() {
        if (AC) { try { AC.abort(); } catch (e) {} }
        observers.forEach(function (o) { try { o.disconnect(); } catch (e) {} });
      };
    }
  };
})();
